  1→// BridgeComponent.h
  2→// Claude Code → UE5.7 File-Based Bridge
  3→// Part of "The Translators" cognitive profiling game
  4→//
  5→// This component watches ~/.translators/ for file changes and handles:
  6→// - state.json: Questions from Claude Code
  7→// - answer.json: User responses back to Claude
  8→// - cognitive_substrate.usda: USD cognitive profile
  9→//
 10→// CRITICAL: USD Stage Actor does NOT auto-reload files.
 11→// We must trigger SetRootLayer() manually on file change.
 12→
 13→#pragma once
 14→
 15→#include "CoreMinimal.h"
 16→#include "Components/ActorComponent.h"
 17→#include "Dom/JsonObject.h"
 18→#include "BridgeComponent.generated.h"
 19→
 20→// Forward declare for editor-only directory watcher
 21→#if WITH_DIRECTORY_WATCHER
 22→struct FFileChangeData;
 23→#endif
 24→
 25→// Note: USD Stage Actor integration is handled via Blueprint
 26→// The OnUsdUpdated delegate notifies when cognitive_substrate.usda changes
 27→
 28→// Delegate for question received from Claude Code
 29→DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnQuestionReceived, const FString&, QuestionJson);
 30→
 31→// Delegate for transition command
 32→DECLARE_DYNAMIC_MULTICAST_DELEGATE_TwoParams(FOnTransitionReceived, const FString&, Direction, const FString&, NextScene);
 33→
 34→// Delegate for finale
 35→DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnFinaleReceived, const FString&, UsdPath);
 36→
 37→// Delegate for USD file update
 38→DECLARE_DYNAMIC_MULTICAST_DELEGATE(FOnUsdUpdated);
 39→
 40→// Delegate for ready state
 41→DECLARE_DYNAMIC_MULTICAST_DELEGATE_OneParam(FOnBridgeReady, int32, TotalQuestions);
 42→
 43→// Structured question data for Blueprints
 44→USTRUCT(BlueprintType)
 45→struct FTranslatorsQuestion
 46→{
 47→    GENERATED_BODY()
 48→
 49→    UPROPERTY(BlueprintReadOnly)
 50→    int32 Index = 0;
 51→
 52→    UPROPERTY(BlueprintReadOnly)
 53→    int32 Total = 0;
 54→
 55→    UPROPERTY(BlueprintReadOnly)
 56→    FString QuestionId;
 57→
 58→    UPROPERTY(BlueprintReadOnly)
 59→    FString Text;
 60→
 61→    UPROPERTY(BlueprintReadOnly)
 62→    FString Scene;
 63→
 64→    UPROPERTY(BlueprintReadOnly)
 65→    TArray<FString> OptionLabels;
 66→
 67→    UPROPERTY(BlueprintReadOnly)
 68→    TArray<FString> OptionDirections;
 69→
 70→    /** Depth tier label: SURFACE, PATTERNS, FEELINGS, CORE */
 71→    UPROPERTY(BlueprintReadOnly)
 72→    FString DepthLabel;
 73→};
 74→
 75→
 76→// Cognitive profile trait (from profile USDA)
 77→USTRUCT(BlueprintType)
 78→struct FTranslatorsTrait
 79→{
 80→    GENERATED_BODY()
 81→
 82→    UPROPERTY(BlueprintReadOnly)
 83→    FString Dimension;    // e.g. "cognitive_density"
 84→
 85→    UPROPERTY(BlueprintReadOnly)
 86→    FString Label;        // e.g. "Balanced"
 87→
 88→    UPROPERTY(BlueprintReadOnly)
 89→    float Score = 0.0f;   // 0.0 - 1.0
 90→
 91→    UPROPERTY(BlueprintReadOnly)
 92→    FString Behavior;     // e.g. "You can hold moderate complexity"
 93→};
 94→
 95→
 96→// Full cognitive profile result
 97→USTRUCT(BlueprintType)
 98→struct FTranslatorsProfile
 99→{
100→    GENERATED_BODY()
101→
102→    UPROPERTY(BlueprintReadOnly)
103→    TArray<FTranslatorsTrait> Traits;
104→
105→    UPROPERTY(BlueprintReadOnly)
106→    TArray<FString> Insights;
107→
108→    UPROPERTY(BlueprintReadOnly)
109→    FString Checksum;
110→
111→    UPROPERTY(BlueprintReadOnly)
112→    FString Anchor;
113→
114→    bool IsValid() const { return Traits.Num() > 0; }
115→};
116→
117→
118→UCLASS(ClassGroup=(Custom), meta=(BlueprintSpawnableComponent))
119→class TRANSLATORSCARD_API UBridgeComponent : public UActorComponent
120→{
121→    GENERATED_BODY()
122→
123→public:
124→    UBridgeComponent();
125→
126→    virtual void BeginPlay() override;
127→    virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;
128→    virtual void TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction) override;
129→
130→    // === DELEGATES (Bind in Blueprint) ===
131→
132→    /** Fired when a new question arrives from Claude Code */
133→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge")
134→    FOnQuestionReceived OnQuestionReceived;
135→
136→    /** Fired when Claude Code sends transition command */
137→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge")
138→    FOnTransitionReceived OnTransitionReceived;
139→
140→    /** Fired when questionnaire completes */
141→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge")
142→    FOnFinaleReceived OnFinaleReceived;
143→
144→    /** Fired when cognitive_substrate.usda updates */
145→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge")
146→    FOnUsdUpdated OnUsdUpdated;
147→
148→    /** Fired when Claude Code is ready to start */
149→    UPROPERTY(BlueprintAssignable, Category = "Translators Bridge")
150→    FOnBridgeReady OnBridgeReady;
151→
152→    // === BLUEPRINT CALLABLE FUNCTIONS ===
153→
154→    /** Send acknowledgment that UE5 is ready */
155→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
156→    void SendAcknowledge();
157→
158→    /** Send user's answer to Claude Code */
159→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
160→    void SendAnswer(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs);
161→
162→    /** Parse current question into structured data */
163→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
164→    FTranslatorsQuestion GetCurrentQuestion() const;
165→
166→    /** Force reload the USD stage (use if auto-detection fails) */
167→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
168→    void ForceReloadUsdStage();
169→
170→    /** Parse cognitive profile from exported USDA file */
171→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
172→    FTranslatorsProfile ParseCognitiveProfile(const FString& UsdPath);
173→
174→    /** Check if bridge is connected */
175→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
176→    bool IsBridgeConnected() const { return bIsConnected; }
177→
178→    /** Check if using USD mode (v2.0.0) */
179→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
180→    bool IsUsingUsdMode() const { return bUsingUsdMode; }
181→
182→    /** Send acknowledgment via USD (v2.0.0) */
183→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
184→    void SendAcknowledgeUsda();
185→
186→    /** Send answer via USD (v2.0.0) */
187→    UFUNCTION(BlueprintCallable, Category = "Translators Bridge")
188→    void SendAnswerUsda(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs);
189→
190→    // === CONFIGURATION ===
191→
192→    /** Bridge directory path (default: ~/.translators) */
193→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge")
194→    FString BridgePath;
195→
196→    /** Enable verbose logging */
197→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge")
198→    bool bVerboseLogging = false;
199→
200→    /** Debounce time in seconds for file change detection */
201→    UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Translators Bridge")
202→    float DebounceTime = 0.05f;
203→
204→private:
205→    // === FILE WATCHING ===
206→
207→    void SetupFileWatcher();
208→    void TeardownFileWatcher();
209→
210→#if WITH_DIRECTORY_WATCHER
211→    void OnDirectoryChanged(const TArray<FFileChangeData>& Changes);
212→#endif
213→
214→    // === STATE HANDLING ===
215→
216→    void ProcessStateFile();
217→    void HandleReadyState(const TSharedPtr<FJsonObject>& JsonObj);
218→    void HandleQuestionState(const TSharedPtr<FJsonObject>& JsonObj);
219→    void HandleTransitionState(const TSharedPtr<FJsonObject>& JsonObj);
220→    void HandleFinaleState(const TSharedPtr<FJsonObject>& JsonObj);
221→
222→    // === USD NATIVE COMMUNICATION (v2.0.0) ===
