244→// === STATE HANDLING ===
245→
246→void UBridgeComponent::ProcessStateFile()
247→{
248→    // Try USD mode first (v2.0.0)
249→    FString UsdFilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
250→    IPlatformFile& PlatformFile = FPlatformFileManager::Get().GetPlatformFile();
251→
252→    if (PlatformFile.FileExists(*UsdFilePath))
253→    {
254→        if (ProcessBridgeStateUsda())
255→        {
256→            return; // Successfully processed USD
257→        }
258→    }
259→
260→    // Fall back to JSON mode (v1.0.0)
261→    FString FilePath = GetBridgeFilePath(TEXT("state.json"));
262→    FString Content;
263→
264→    BridgeLog(FString::Printf(TEXT("Attempting to read: %s"), *FilePath));
265→
266→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
267→    {
268→        BridgeLog(FString::Printf(TEXT("FAILED to read: %s (exists: %d)"),
269→            *FilePath, PlatformFile.FileExists(*FilePath) ? 1 : 0));
270→        return;
271→    }
272→
273→    // Parse JSON
274→    TSharedPtr<FJsonObject> JsonObj;
275→    TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(Content);
276→
277→    if (!FJsonSerializer::Deserialize(Reader, JsonObj) || !JsonObj.IsValid())
278→    {
279→        BridgeLog(TEXT("ERROR: Invalid JSON in state.json"));
280→        return;
281→    }
282→
283→    CurrentStateJson = Content;
284→    bUsingUsdMode = false;
285→
286→    // Route by type
287→    FString StateType;
288→    if (JsonObj->TryGetStringField(TEXT("type"), StateType))
289→    {
290→        if (StateType == TEXT("ready"))
291→        {
292→            HandleReadyState(JsonObj);
293→        }
294→        else if (StateType == TEXT("question"))
295→        {
296→            HandleQuestionState(JsonObj);
297→        }
298→        else if (StateType == TEXT("transition"))
299→        {
300→            HandleTransitionState(JsonObj);
301→        }
302→        else if (StateType == TEXT("finale"))
303→        {
304→            HandleFinaleState(JsonObj);
305→        }
306→        else
307→        {
308→            BridgeLog(FString::Printf(TEXT("Unknown state type: %s"), *StateType));
309→        }
310→    }
311→}
312→
313→
314→void UBridgeComponent::HandleReadyState(const TSharedPtr<FJsonObject>& JsonObj)
315→{
316→    // Support both flat and nested "ready" object
317→    const TSharedPtr<FJsonObject>* ReadyObjPtr;
318→    const TSharedPtr<FJsonObject>& ReadyData =
319→        JsonObj->TryGetObjectField(TEXT("ready"), ReadyObjPtr) ? *ReadyObjPtr : JsonObj;
320→
321→    int32 TotalQuestions = ReadyData->GetIntegerField(TEXT("total_questions"));
322→    FString FirstScene = ReadyData->GetStringField(TEXT("first_scene"));
323→
324→    BridgeLog(FString::Printf(TEXT("Claude Code ready! Total questions: %d, First scene: %s"),
325→        TotalQuestions, *FirstScene));
326→
327→    bIsConnected = true;
328→    OnBridgeReady.Broadcast(TotalQuestions);
329→}
330→
331→
332→void UBridgeComponent::HandleQuestionState(const TSharedPtr<FJsonObject>& JsonObj)
333→{
334→    // Protocol nests question data under "question" key, but also support flat format
335→    const TSharedPtr<FJsonObject>* QuestionObjPtr;
336→    const TSharedPtr<FJsonObject>& QuestionData =
337→        JsonObj->TryGetObjectField(TEXT("question"), QuestionObjPtr) ? *QuestionObjPtr : JsonObj;
338→
339→    // Parse into struct
340→    CurrentQuestion = FTranslatorsQuestion();
341→    CurrentQuestion.Index = QuestionData->GetIntegerField(TEXT("index"));
342→    CurrentQuestion.Total = QuestionData->GetIntegerField(TEXT("total"));
343→    CurrentQuestion.QuestionId = QuestionData->GetStringField(TEXT("id"));
344→    CurrentQuestion.Text = QuestionData->GetStringField(TEXT("text"));
345→    CurrentQuestion.Scene = QuestionData->GetStringField(TEXT("scene"));
346→
347→    // Parse options array
348→    const TArray<TSharedPtr<FJsonValue>>* OptionsArray;
349→    if (QuestionData->TryGetArrayField(TEXT("options"), OptionsArray))
350→    {
351→        for (const TSharedPtr<FJsonValue>& OptionVal : *OptionsArray)
352→        {
353→            const TSharedPtr<FJsonObject>& OptionObj = OptionVal->AsObject();
354→            if (OptionObj.IsValid())
355→            {
356→                CurrentQuestion.OptionLabels.Add(OptionObj->GetStringField(TEXT("label")));
357→                CurrentQuestion.OptionDirections.Add(OptionObj->GetStringField(TEXT("direction")));
358→            }
359→        }
360→    }
361→
362→    // Assign depth label based on question index
363→    CurrentQuestion.DepthLabel = GetDepthLabelForIndex(CurrentQuestion.Index);
364→
365→    BridgeLog(FString::Printf(TEXT("Question %d/%d [%s]: %s"),
366→        CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.DepthLabel, *CurrentQuestion.QuestionId));
367→
368→    // Broadcast raw JSON for flexible handling
369→    OnQuestionReceived.Broadcast(CurrentStateJson);
370→}
371→
372→
373→void UBridgeComponent::HandleTransitionState(const TSharedPtr<FJsonObject>& JsonObj)
374→{
375→    const TSharedPtr<FJsonObject>* TransObjPtr;
376→    const TSharedPtr<FJsonObject>& TransData =
377→        JsonObj->TryGetObjectField(TEXT("transition"), TransObjPtr) ? *TransObjPtr : JsonObj;
378→
379→    FString Direction = TransData->GetStringField(TEXT("direction"));
380→    FString NextScene = TransData->GetStringField(TEXT("next_scene"));
381→    float Progress = TransData->GetNumberField(TEXT("progress"));
382→
383→    BridgeLog(FString::Printf(TEXT("Transition: %s -> %s (%.0f%%)"),
384→        *Direction, *NextScene, Progress * 100.0f));
385→
386→    OnTransitionReceived.Broadcast(Direction, NextScene);
387→}
388→
389→
390→void UBridgeComponent::HandleFinaleState(const TSharedPtr<FJsonObject>& JsonObj)
391→{
392→    const TSharedPtr<FJsonObject>* FinaleObjPtr;
393→    const TSharedPtr<FJsonObject>& FinaleData =
394→        JsonObj->TryGetObjectField(TEXT("finale"), FinaleObjPtr) ? *FinaleObjPtr : JsonObj;
395→
396→    FString UsdPath = FinaleData->GetStringField(TEXT("usd_path"));
397→    FString Message = FinaleData->GetStringField(TEXT("message"));
398→
399→    BridgeLog(FString::Printf(TEXT("FINALE: %s"), *Message));

