for a in actors:
    if a.get_actor_label() == "{actor_label}":
        actor = a
        break

if actor is None:
    print("RESULT:" + json.dumps({{"error": "Actor not found: {actor_label}"}}))
else:
    comp_class = getattr(unreal, "{component_class}", None)
