    def Xform "Answers" (
        doc = "Individual question responses"
    )
    {{
{"".join(answer_prims)}
    }}
}}
'''

    # Write file
    with open(PROFILE_FILE, 'w', encoding='utf-8') as f:
        f.write(usda_content)

    return str(PROFILE_FILE), checksum

