        direction = escape_usda_string(opt.get("direction", ""))
        semantic_tag = escape_usda_string(opt.get("semantic_tag", ""))
        options_usda += f'''
        def Xform "Option_{i}" {{
            int index = {i}
            string label = "{label}"
            string direction = "{direction}"
            string semantic_tag = "{semantic_tag}"
        }}
'''

    usda_content = f'''#usda 1.0
