  +-----------------------------------------------------------+{Colors.RESET}
""")

def print_progress(current: int, total: int):
    filled = int((current / total) * 30)
    bar = "#" * filled + "." * (30 - filled)
    print(f"\n  {Colors.CYAN}Progress: [{bar}] {current}/{total}{Colors.RESET}")

def print_question(q: dict, index: int, total: int):
