    except Exception:
        pass

# Read and encode the image if it exists
image_b64 = ""
if os.path.exists(out_path):
    with open(out_path, "rb") as f:
        image_b64 = base64.b64encode(f.read()).decode("ascii")
    os.remove(out_path)

result = {{
    "image": image_b64,
