        print("RESULT:" + json.dumps({{"error": "Component class not found: {component_class}"}}))
    else:
        comp = unreal.new_object(comp_class, actor, "{comp_name}")
        if comp and actor.root_component:
            comp.k2_attach_to(actor.root_component)

