        ry: float | None = None,
        rz: float | None = None,
        sx: float | None = None,
        sy: float | None = None,
        sz: float | None = None,
    ) -> str:
        """Set location (x,y,z), rotation (rx,ry,rz), and/or scale (sx,sy,sz) on an actor."""
