"""Viewport perception tools for UE5 MCP server.

Consumes from the ViewportPerception C++ plugin's HTTP endpoint (port 30011).
Falls back to SceneCapture2D via ue_execute_python if the plugin is unavailable.

Tier 3I: Includes bridge state correlation — viewport frames are tagged with
the current game state (question, sync_status) for full situational awareness.
"""

from __future__ import annotations

import json
import os
import re
import time
from pathlib import Path

import httpx

PERCEPTION_URL = os.environ.get("UE_PERCEPTION_URL", "http://localhost:30011")
PERCEPTION_TIMEOUT = 5.0
BRIDGE_DIR = Path.home() / ".translators"


def _read_bridge_state() -> dict | None:
    """Read current bridge state from bridge_state.usda (non-blocking, best-effort)."""
    state_file = BRIDGE_DIR / "bridge_state.usda"
    heartbeat_file = BRIDGE_DIR / "heartbeat.json"

    result = {
        "bridge_connected": False,
        "sync_status": None,
        "message_type": None,
        "current_question": None,
        "question_index": None,
        "question_total": None,
        "heartbeat_alive": False,
    }

    # Read bridge state
    if state_file.exists():
        try:
            content = state_file.read_text(encoding="utf-8")
            result["bridge_connected"] = True

            sync_match = re.search(r'string sync_status = "([^"]*)"', content)
            type_match = re.search(r'string message_type = "([^"]*)"', content)
            qid_match = re.search(r'string question_id = "([^"]*)"', content)
            idx_match = re.search(r'int index = (\d+)', content)
            total_match = re.search(r'int total = (\d+)', content)
            text_match = re.search(r'string text = "([^"]*)"', content)

            result["sync_status"] = sync_match.group(1) if sync_match else None
            result["message_type"] = type_match.group(1) if type_match else None
            result["current_question"] = qid_match.group(1) if qid_match else None
            result["question_index"] = int(idx_match.group(1)) if idx_match else None
            result["question_total"] = int(total_match.group(1)) if total_match else None
            if text_match and text_match.group(1):
                result["question_text"] = text_match.group(1)[:100]  # Truncate for payload size
        except (OSError, PermissionError):
            pass

    # Check heartbeat
    if heartbeat_file.exists():
        try:
            age = time.time() - heartbeat_file.stat().st_mtime
            result["heartbeat_alive"] = age < 15
            result["heartbeat_age_s"] = round(age, 1)
        except OSError:
            pass

    return result


async def _perception_request(method: str, path: str, body: dict | None = None) -> dict | None:
    """Make an HTTP request to the perception endpoint. Returns None on connection failure."""
    try:
        async with httpx.AsyncClient(base_url=PERCEPTION_URL, timeout=PERCEPTION_TIMEOUT) as client:
            if method == "GET":
                r = await client.get(path)
            else:
                r = await client.put(path, json=body or {})
            r.raise_for_status()
            return r.json()
    except (httpx.ConnectError, httpx.TimeoutException, httpx.HTTPStatusError):
        return None


async def _fallback_capture(ue, width: int, height: int, format: str) -> dict:
    """Fallback: capture via SceneCapture2D + Python in the editor.

    This re-renders the scene (performance cost) but works without the C++ plugin.
    """
    code = f"""
import unreal, json, base64, os, tempfile

# Get viewport info
world = unreal.EditorLevelLibrary.get_editor_world()
subsystem = unreal.get_editor_subsystem(unreal.EditorActorSubsystem)
actors = subsystem.get_all_level_actors()
level_name = world.get_name() if world else "Unknown"

# Get active viewport camera
ecs = unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem)
loc, rot = unreal.Vector(), unreal.Rotator()
try:
    vp = unreal.EditorLevelLibrary
    loc = ecs.get_level_viewport_camera_info()[0] if hasattr(ecs, 'get_level_viewport_camera_info') else unreal.Vector()
    rot = ecs.get_level_viewport_camera_info()[1] if hasattr(ecs, 'get_level_viewport_camera_info') else unreal.Rotator()
except Exception:
    pass

# Selected actors
selected = []
sel = unreal.EditorUtilityLibrary.get_selected_assets() if hasattr(unreal, 'EditorUtilityLibrary') else []
try:
    sel_actors = unreal.get_editor_subsystem(unreal.EditorActorSubsystem).get_selected_level_actors()
    selected = [a.get_actor_label() for a in sel_actors]
except Exception:
    pass

# Capture via screenshot
tmp_dir = tempfile.gettempdir().replace("\\\\", "/")
out_path = tmp_dir + "/ue_perception_capture.{format}"

# Use high-res screenshot
success = False
try:
    unreal.AutomationLibrary.take_high_res_screenshot({width}, {height}, out_path)
    success = True
except Exception:
    pass

if not success:
    # Fallback: use viewport screenshot command
    try:
        cmd = f"HighResShot {width}x{height}"
        unreal.SystemLibrary.execute_console_command(world, cmd)
    except Exception:
        pass

# Read and encode the image if it exists
image_b64 = ""
if os.path.exists(out_path):
    with open(out_path, "rb") as f:
        image_b64 = base64.b64encode(f.read()).decode("ascii")
    os.remove(out_path)

result = {{
    "image": image_b64,
    "width": {width},
    "height": {height},
    "format": "{format}",
    "frame_number": 0,
    "timestamp": 0,
    "camera": {{
        "location": [loc.x, loc.y, loc.z] if hasattr(loc, 'x') else [0, 0, 0],
        "rotation": [rot.pitch, rot.yaw, rot.roll] if hasattr(rot, 'pitch') else [0, 0, 0],
        "fov": 90.0
    }},
    "viewport": {{
        "size": [{width}, {height}],
        "type": "LevelEditor"
    }},
    "selection": selected,
    "scene": {{
        "map": level_name,
        "actor_count": len(actors)
    }},
    "timing": {{
        "delta_time": 0,
        "fps": 0
    }},
    "fallback": True
}}
print("RESULT:" + json.dumps(result))
"""
    return await ue.execute_python(code)


def register(server, ue):

    @server.tool(
        name="ue_viewport_percept",
        description=(
            "Capture the UE5 editor viewport -- returns the rendered frame as an image "
            "plus camera, selection, and scene metadata. Gives the AI situated visual awareness."
        ),
        annotations={
            "readOnlyHint": True,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def viewport_percept(
        width: int = 1280,
        height: int = 720,
        format: str = "jpeg",
        include_image: bool = True,
    ) -> str:
        """Capture a single viewport perception packet with correlated game state."""

        # Try the C++ plugin endpoint first
        result = await _perception_request("GET", "/perception/frame")

        if result is None:
            # Plugin not available -- try single-shot endpoint
            result = await _perception_request("PUT", "/perception/single", {
                "width": width,
                "height": height,
                "format": format,
            })

        if result is None:
            # Fall back to Python-based capture
            fallback = await _fallback_capture(ue, width, height, format)
            if fallback.get("error"):
                return json.dumps({
                    "error": "Viewport perception unavailable",
                    "detail": fallback["error"],
                    "hint": "Ensure the ViewportPerception plugin is enabled, or that the editor is running.",
                }, indent=2)
            result = fallback.get("result", fallback)

        if not include_image and isinstance(result, dict):
            result.pop("image", None)

        # Correlate with bridge game state
        if isinstance(result, dict):
            bridge_state = _read_bridge_state()
            if bridge_state:
                result["game_state"] = bridge_state

        return json.dumps(result, indent=2)

    @server.tool(
        name="ue_viewport_watch",
        description=(
            "Start or stop continuous viewport awareness at the specified rate. "
            "When active, the perception system captures frames continuously."
        ),
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def viewport_watch(
        action: str = "start",
        fps: float = 5.0,
        width: int = 768,
        height: int = 432,
    ) -> str:
        """Start/stop continuous viewport perception."""

        if action == "start":
            result = await _perception_request("PUT", "/perception/start", {
                "fps": fps,
                "width": width,
                "height": height,
            })
            if result is None:
                return json.dumps({
                    "error": f"ViewportPerception plugin not reachable at {PERCEPTION_URL}",
                    "hint": "Continuous capture requires the C++ plugin. Use ue_viewport_percept for single-shot capture.",
                }, indent=2)
            return json.dumps(result, indent=2)

        elif action == "stop":
            result = await _perception_request("PUT", "/perception/stop")
            if result is None:
                return json.dumps({"status": "stopped", "note": "Plugin was not reachable"}, indent=2)
            return json.dumps(result, indent=2)

        return json.dumps({"error": f"Unknown action '{action}'. Use 'start' or 'stop'."}, indent=2)

    @server.tool(
        name="ue_viewport_config",
        description="Configure the viewport perception system (resolution, format, capture rate).",
        annotations={
            "readOnlyHint": False,
            "destructiveHint": False,
            "idempotentHint": True,
        },
    )
    async def viewport_config(
        max_fps: float | None = None,
        width: int | None = None,
        height: int | None = None,
        format: str | None = None,
        quality: int | None = None,
    ) -> str:
        """Configure the perception system. Only provided fields are updated."""

        config = {}
        if max_fps is not None:
            config["max_fps"] = max_fps
        if width is not None:
            config["width"] = width
        if height is not None:
            config["height"] = height
        if format is not None:
            config["format"] = format
        if quality is not None:
            config["quality"] = quality

        if not config:
            # Query current status
            result = await _perception_request("GET", "/perception/status")
            if result is None:
                return json.dumps({"error": "ViewportPerception plugin not reachable"}, indent=2)
            return json.dumps(result, indent=2)

        result = await _perception_request("PUT", "/perception/config", config)
        if result is None:
            return json.dumps({
                "error": f"ViewportPerception plugin not reachable at {PERCEPTION_URL}",
                "hint": "Configuration requires the C++ plugin to be running.",
            }, indent=2)
        return json.dumps(result, indent=2)

"""
usd_bridge.py

USD-Native Bridge Communication for CC↔UE5

This module provides functions to read/write USD files for bridge communication,
replacing the JSON-based state.json/answer.json protocol with USD composition semantics.

Key Functions:
- write_question_usda(): Write question to bridge_state.usda
- read_answer_usda(): Read answer from bridge_state.usda
- write_transition_usda(): Write transition state
- write_finale_usda(): Write finale with profile reference
- set_variant(): Set USD variant selection (state machine)

USD Advantages over JSON:
- VariantSets provide native state machine without code
- Composition semantics (LIVRPS) resolve conflicts automatically
- References pull in full cognitive substrate
- Schema validation built into USD

Requirements:
- pip install usd-core (OpenUSD Python bindings)
- Falls back to text-based USDA generation if pxr unavailable

Author: Translators Bridge v2.0.0
"""

from datetime import datetime
import os
from pathlib import Path
import re
import tempfile
from typing import Optional, Dict, Any, List

# Try to import OpenUSD Python bindings
try:
    from pxr import Usd, Sdf, UsdGeom
    HAS_PXR = True
except ImportError:
    HAS_PXR = False
    print("[USD Bridge] Warning: pxr not available, using text-based USDA generation")


# ═══════════════════════════════════════════════════════════════════════════════
# CONFIGURATION
# ═══════════════════════════════════════════════════════════════════════════════

DEFAULT_BRIDGE_PATH = Path.home() / ".translators"
BRIDGE_STATE_FILE = "bridge_state.usda"
BRIDGE_VERSION = "2.0.0"


# ═══════════════════════════════════════════════════════════════════════════════
# ATOMIC FILE I/O
# ═══════════════════════════════════════════════════════════════════════════════

def _atomic_write(file_path: Path, content: str) -> None:
    """Write content to file atomically via tmp + os.replace (NTFS-safe)."""
    parent = file_path.parent
    fd, tmp_path = tempfile.mkstemp(dir=str(parent), suffix=".tmp", prefix=".bridge_")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as f:
            f.write(content)
        os.replace(tmp_path, str(file_path))
    except BaseException:
        # Clean up temp file on any failure
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise


def _safe_read(file_path: Path, retries: int = 3, delay: float = 0.05) -> Optional[str]:
    """Read file with retry on Windows file-lock errors."""
    import time
    for attempt in range(retries):
        try:
            return file_path.read_text(encoding="utf-8")
        except (PermissionError, OSError):
            if attempt < retries - 1:
                time.sleep(delay * (2 ** attempt))  # Exponential backoff
    return None


# ═══════════════════════════════════════════════════════════════════════════════
# CORE USD FUNCTIONS (using pxr when available)
# ═══════════════════════════════════════════════════════════════════════════════

def _validate_bridge_path(bridge_path: Optional[Path]) -> Path:
    """Validate and resolve a bridge path, preventing path traversal.

    All bridge file operations MUST go through this function to ensure
    files stay within the expected bridge directory.
    """
    base_path = (bridge_path or DEFAULT_BRIDGE_PATH).resolve()
    allowed_root = DEFAULT_BRIDGE_PATH.resolve()
    try:
        base_path.relative_to(allowed_root)
    except ValueError:
        raise ValueError(
            f"Bridge path '{base_path}' is outside the allowed directory '{allowed_root}'. "
            f"Path traversal is not permitted."
        )
    return base_path


def get_bridge_file_path(bridge_path: Optional[Path] = None) -> Path:
    """Get path to bridge_state.usda."""
    base_path = _validate_bridge_path(bridge_path)
    return base_path / BRIDGE_STATE_FILE


def ensure_bridge_directory(bridge_path: Optional[Path] = None) -> Path:
    """Ensure bridge directory exists."""
    base_path = _validate_bridge_path(bridge_path)
    base_path.mkdir(parents=True, exist_ok=True)
    return base_path


def get_timestamp() -> str:
    """Get ISO 8601 timestamp."""
    from datetime import timezone
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")


# ═══════════════════════════════════════════════════════════════════════════════
# QUESTION WRITING
# ═══════════════════════════════════════════════════════════════════════════════

def write_question_usda(
    question_id: str,
    text: str,
    options: List[Dict[str, str]],
    index: int,
    total: int,
    scene: str = "",
    bridge_path: Optional[Path] = None
) -> Path:
    """
    Write a question to bridge_state.usda.

    Args:
        question_id: Unique identifier for the question (e.g., "load", "ground")
        text: Question text to display
        options: List of dicts with 'label' and 'direction' keys
        index: 0-based question index
        total: Total number of questions
        scene: Scene identifier for visual transitions
        bridge_path: Optional custom bridge directory

    Returns:
        Path to the written USDA file

    Example:
        write_question_usda(
            question_id="load",
            text="When working on a complex problem, do you prefer to...",
            options=[
                {"label": "Break it into small pieces", "direction": "low"},
                {"label": "See the full picture first", "direction": "high"},
                {"label": "Jump between both", "direction": "mid"}
            ],
            index=0,
            total=8
        )
    """
    ensure_bridge_directory(bridge_path)
    file_path = get_bridge_file_path(bridge_path)
    timestamp = get_timestamp()

    if HAS_PXR:
        return _write_question_pxr(
            file_path, question_id, text, options, index, total, scene, timestamp
        )
    else:
        return _write_question_text(
            file_path, question_id, text, options, index, total, scene, timestamp
        )


def _write_question_pxr(
    file_path: Path,
    question_id: str,
    text: str,
    options: List[Dict[str, str]],
    index: int,
    total: int,
    scene: str,
    timestamp: str
) -> Path:
    """Write question using pxr USD library."""
    # Create or open stage
    if file_path.exists():
        stage = Usd.Stage.Open(str(file_path))
    else:
        stage = Usd.Stage.CreateNew(str(file_path))
        stage.SetDefaultPrim(stage.DefinePrim("/BridgeState", "Xform"))

    root = stage.GetPrimAtPath("/BridgeState")

    # Set variants for state machine
    vsets = root.GetVariantSets()
    if vsets.HasVariantSet("sync_status"):
        vsets.GetVariantSet("sync_status").SetVariantSelection("question_pending")
    if vsets.HasVariantSet("message_type"):
        vsets.GetVariantSet("message_type").SetVariantSelection("question")

    # Write message data
    msg_prim = stage.GetPrimAtPath("/BridgeState/Message")
    if msg_prim:
        msg_prim.GetAttribute("type").Set("question")
        msg_prim.GetAttribute("index").Set(index)
        msg_prim.GetAttribute("total").Set(total)
        msg_prim.GetAttribute("timestamp").Set(timestamp)
        msg_prim.GetAttribute("question_id").Set(question_id)
        msg_prim.GetAttribute("text").Set(text)
        msg_prim.GetAttribute("scene").Set(scene)
        msg_prim.GetAttribute("progress_display").Set(f"{index + 1}/{total}")

    # Write options
    for i, opt in enumerate(options[:3]):
        opt_prim = stage.GetPrimAtPath(f"/BridgeState/Options/Option_{i}")
        if opt_prim:
            opt_prim.GetAttribute("index").Set(i)
            opt_prim.GetAttribute("label").Set(opt.get("label", ""))
            opt_prim.GetAttribute("direction").Set(opt.get("direction", ""))
            opt_prim.GetAttribute("semantic_tag").Set(opt.get("semantic_tag", ""))

    stage.Save()
    return file_path


def _update_question_incremental(
    file_path: Path,
    question_id: str,
    text: str,
    options: List[Dict[str, str]],
    index: int,
    total: int,
    scene: str,
    timestamp: str
) -> bool:
    """Incrementally update an existing bridge_state.usda (patch, not rewrite).

    Returns True if successful, False if full rewrite needed (file missing/corrupt).
    """
    content = _safe_read(file_path)
    if content is None or 'def Xform "Message"' not in content:
        return False

    def esc(s: str) -> str:
        return s.replace('\\', '\\\\').replace('"', '\\"').replace('\n', '\\n')

    # 1. Update variants
    content = re.sub(r'(string sync_status = ")[^"]*(")', r'\g<1>question_pending\g<2>', content)
    content = re.sub(r'(string message_type = ")[^"]*(")', r'\g<1>question\g<2>', content)

    # 2. Replace Message prim
    new_message = f'''def Xform "Message" {{
        string type = "question"
        int index = {index}
        int total = {total}
        string timestamp = "{timestamp}"
        string question_id = "{esc(question_id)}"
        string text = "{esc(text)}"
        string scene = "{esc(scene)}"
        string progress_display = "{index + 1}/{total}"
    }}'''
    content = re.sub(r'def Xform "Message"[^}]*\}', new_message, content, flags=re.DOTALL)

    # 3. Replace Options prim (rebuild with new options)
    options_inner = ""
    for i, opt in enumerate(options[:3]):
        label = esc(opt.get("label", ""))
        direction = esc(opt.get("direction", ""))
        semantic_tag = esc(opt.get("semantic_tag", ""))
        options_inner += f'''
        def Xform "Option_{i}" {{
            int index = {i}
            string label = "{label}"
            string direction = "{direction}"
            string semantic_tag = "{semantic_tag}"
        }}
'''
    new_options = f'def Xform "Options" {{{options_inner}    }}'
    content = re.sub(r'def Xform "Options"[^}]*(?:\{[^}]*\}[^}]*)*\}', new_options, content, flags=re.DOTALL)

    # 4. Reset answer prim for new question
    new_answer = '''def Xform "Answer" {
        string question_id = ""
        int option_index = -1
        double response_time_ms = 0.0
        string selected_label = ""
        string selected_direction = ""
        string timestamp = ""
    }'''
    content = re.sub(r'def Xform "Answer"[^}]*\}', new_answer, content, flags=re.DOTALL)

    _atomic_write(file_path, content)
    return True


